const { useState } = React;

const IMG_A = "http://blog-hostimaging.oss-cn-beijing.aliyuncs.com/wallhaven-9d3181_bd5ad183-67ed-42b1-bd31-6eea57e3388d.webp";
const IMG_B = "http://blog-hostimaging.oss-cn-beijing.aliyuncs.com/wallhaven-4lol1r_920d1162-f760-456a-8dc0-a03f62dfbfe2.webp";

// CSS 代码视图：函数名与正在变化的值高亮
const CssView = ({ lines }) => (
  <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, index) => (
      <div key={index}>
        {line.map((part, partIndex) =>
          typeof part === "string" ? (
            <span key={partIndex}>{part}</span>
          ) : (
            <span key={partIndex} className={part.fn ? "text-accent-text" : "rounded-tau-sm bg-accent-soft px-0.5 text-accent-text"}>
              {part.text}
            </span>
          )
        )}
      </div>
    ))}
  </pre>
);
const Thumb = ({ src, label }) => (
  <div className="relative size-10 shrink-0 overflow-hidden rounded-tau-sm border border-line-1 bg-cover bg-center" style={{ backgroundImage: `url("${src}")` }}>
    <span className="absolute bottom-0 left-0 rounded-tr-[6px] bg-surface/90 px-1 font-tau-mono text-tau-tiny text-ink-1">{label}</span>
  </div>
);

const Component = () => {
  const [percent, setPercent] = useState(50);

  return (
    <div className="flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-range { accent-color: var(--tau-accent); }
        }
      `}</style>
      <div
        className="relative h-[240px] w-full overflow-hidden rounded-tau-md border border-line-1 bg-hover bg-cover bg-center"
        style={{ backgroundImage: `-webkit-cross-fade(url("${IMG_A}"), url("${IMG_B}"), ${percent}%)` }}
      >
        <span className="absolute left-3 top-3 rounded-full bg-surface/90 px-2.5 py-0.5 text-tau-sm text-ink-2 shadow-card">
          合成结果
        </span>
      </div>
      <div className="flex items-center gap-3">
        <Thumb src={IMG_A} label="A" />
        <span className="w-12 shrink-0 font-tau-mono text-tau-sm text-ink-1">{percent}%</span>
        <input
          type="range"
          min={0}
          max={100}
          value={percent}
          aria-label="图片 A 的不透明度"
          onChange={event => setPercent(Number(event.target.value))}
          className="cb-range h-1.5 flex-1 cursor-pointer"
        />
        <span className="w-12 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{100 - percent}%</span>
        <Thumb src={IMG_B} label="B" />
      </div>
      <CssView
        lines={[
          ["background-image: ", { fn: true, text: "-webkit-cross-fade" }, "("],
          ["  ", { fn: true, text: "url" }, '("mountain.webp"),'],
          ["  ", { fn: true, text: "url" }, '("city.webp"),'],
          ["  ", { text: `${percent}%` }],
          [");"],
        ]}
      />
    </div>
  );
};

const { useEffect, useRef, useState } = React;

const IMG_A = "http://blog-hostimaging.oss-cn-beijing.aliyuncs.com/wallhaven-9d3181_bd5ad183-67ed-42b1-bd31-6eea57e3388d.webp";
const IMG_B = "http://blog-hostimaging.oss-cn-beijing.aliyuncs.com/wallhaven-4lol1r_920d1162-f760-456a-8dc0-a03f62dfbfe2.webp";
const DURATION_MS = 1500;

// CSS 代码视图：函数名与正在变化的值高亮
const CssView = ({ lines }) => (
  <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, index) => (
      <div key={index}>
        {line.map((part, partIndex) =>
          typeof part === "string" ? (
            <span key={partIndex}>{part}</span>
          ) : (
            <span key={partIndex} className={part.fn ? "text-accent-text" : "rounded-tau-sm bg-accent-soft px-0.5 text-accent-text"}>
              {part.text}
            </span>
          )
        )}
      </div>
    ))}
  </pre>
);
const Thumb = ({ src, label }) => (
  <div className="relative size-10 shrink-0 overflow-hidden rounded-tau-sm border border-line-1 bg-cover bg-center" style={{ backgroundImage: `url("${src}")` }}>
    <span className="absolute bottom-0 left-0 rounded-tr-[6px] bg-surface/90 px-1 font-tau-mono text-tau-tiny text-ink-1">{label}</span>
  </div>
);

const Component = () => {
  const boxRef = useRef(null);
  const frameRef = useRef(0);
  const [showB, setShowB] = useState(false);
  const [percent, setPercent] = useState(100);

  // 过渡期间逐帧读取 --cf-percent 的插值结果，驱动进度读数
  useEffect(() => {
    const box = boxRef.current;
    box.style.setProperty("--cf-percent", showB ? "0%" : "100%");
    let start = 0;
    const tick = now => {
      start ||= now;
      setPercent(parseFloat(getComputedStyle(box).getPropertyValue("--cf-percent")) || 0);
      if (now - start < DURATION_MS + 100) frameRef.current = requestAnimationFrame(tick);
    };
    frameRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameRef.current);
  }, [showB]);

  const choose = (nextShowB, src, label) => (
    <button
      type="button"
      onClick={() => setShowB(nextShowB)}
      aria-pressed={showB === nextShowB}
      className={`flex cursor-pointer items-center gap-2 rounded-tau-sm border py-1 pl-1 pr-3 text-tau-body transition-colors ${
        showB === nextShowB ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
      }`}
    >
      <Thumb src={src} label={label} />
      图片 {label}
    </button>
  );

  return (
    <div className="flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-crossfade {
            background-image: -webkit-cross-fade(url("${IMG_A}"), url("${IMG_B}"), var(--cf-percent));
            transition: --cf-percent ${DURATION_MS}ms ease-in-out;
          }
        }
        @property --cf-percent {
          syntax: "<percentage>";
          inherits: false;
          initial-value: 100%;
        }
      `}</style>
      <div ref={boxRef} className="cb-crossfade relative h-[240px] w-full overflow-hidden rounded-tau-md border border-line-1 bg-hover bg-cover bg-center">
        <span className="absolute left-3 top-3 rounded-full bg-surface/90 px-2.5 py-0.5 text-tau-sm text-ink-2 shadow-card">
          --cf-percent: {Math.round(percent)}%
        </span>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        {choose(false, IMG_A, "A")}
        {choose(true, IMG_B, "B")}
        <div className="ml-auto flex min-w-[160px] flex-1 items-center gap-2">
          <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-track">
            <div className="h-full rounded-full bg-accent" style={{ width: `${percent}%` }} />
          </div>
          <span className="w-10 text-right font-tau-mono text-tau-sm text-ink-2">{Math.round(percent)}%</span>
        </div>
      </div>
      <CssView
        lines={[
          [{ fn: true, text: "@property" }, " --cf-percent {"],
          ['  syntax: "<percentage>";'],
          ["  inherits: false;"],
          ["  initial-value: 100%;"],
          ["}"],
          [""],
          [".element {"],
          ["  background-image: ", { fn: true, text: "-webkit-cross-fade" }, '(url("a.webp"), url("b.webp"), ', { fn: true, text: "var" }, "(--cf-percent));"],
          ["  transition: --cf-percent 1.5s ease-in-out;"],
          ["}"],
          [""],
          [".element.show-b {"],
          ["  --cf-percent: ", { text: "0%" }, ";"],
          ["}"],
        ]}
      />
    </div>
  );
};

const { useState } = React;

// CSS 代码视图：函数名与正在变化的值高亮
const CssView = ({ lines }) => (
  <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
    {lines.map((line, index) => (
      <div key={index}>
        {line.map((part, partIndex) =>
          typeof part === "string" ? (
            <span key={partIndex}>{part}</span>
          ) : (
            <span key={partIndex} className={part.fn ? "text-accent-text" : "rounded-tau-sm bg-accent-soft px-0.5 text-accent-text"}>
              {part.text}
            </span>
          )
        )}
      </div>
    ))}
  </pre>
);

// 颜色就是演示内容：两种默认色在浅色与深色背景下都清晰可辨
const Swatch = ({ value, onChange, label }) => (
  <label className="relative size-9 shrink-0 cursor-pointer overflow-hidden rounded-full border-2 border-surface shadow-card" style={{ background: value }}>
    <input type="color" value={value} aria-label={label} onChange={event => onChange(event.target.value)} className="absolute inset-0 cursor-pointer opacity-0" />
  </label>
);

const Component = () => {
  const [colorA, setColorA] = useState("#3b82f6");
  const [colorB, setColorB] = useState("#ef4444");
  const [percent, setPercent] = useState(50);

  return (
    <div className="flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-range { accent-color: var(--tau-accent); }
        }
      `}</style>
      <div
        className="h-[144px] w-full rounded-tau-md border border-line-1"
        style={{ backgroundImage: `-webkit-cross-fade(linear-gradient(${colorA}, ${colorA}), linear-gradient(${colorB}, ${colorB}), ${percent}%)` }}
      />
      <div className="flex items-center gap-3">
        <Swatch value={colorA} onChange={setColorA} label="颜色 A" />
        <span className="w-12 shrink-0 font-tau-mono text-tau-sm text-ink-1">{percent}%</span>
        <input
          type="range"
          min={0}
          max={100}
          value={percent}
          aria-label="颜色 A 的比例"
          onChange={event => setPercent(Number(event.target.value))}
          className="cb-range h-1.5 flex-1 cursor-pointer"
        />
        <span className="w-12 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{100 - percent}%</span>
        <Swatch value={colorB} onChange={setColorB} label="颜色 B" />
      </div>
      <CssView
        lines={[
          ["background-image: ", { fn: true, text: "-webkit-cross-fade" }, "("],
          ["  ", { fn: true, text: "linear-gradient" }, "(", { text: colorA }, ", ", { text: colorA }, "),"],
          ["  ", { fn: true, text: "linear-gradient" }, "(", { text: colorB }, ", ", { text: colorB }, "),"],
          ["  ", { text: `${percent}%` }],
          [");"],
        ]}
      />
    </div>
  );
};
